#!/usr/bin/env python3
"""Create a local, offline annotation UI. No remote calls or credentials."""
import argparse,json,pathlib,sys
sys.path.insert(0,str(pathlib.Path(__file__).resolve().parents[1]/'site'))
from topics_evaluate import validate_gold,digest
ROOT=pathlib.Path(__file__).resolve().parents[1]

def review_html(dataset):
    payload=json.dumps(dataset,ensure_ascii=False).replace('<','\\u003c')
    return '''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AI4S 人工标注评审</title><style>body{font:16px system-ui;max-width:1050px;margin:24px auto;padding:16px}button,input,select,textarea{font:inherit;margin:6px;padding:8px}textarea{width:90%;min-height:70px}label{display:inline-block}fieldset{margin:12px 0}article{background:#f4f5f7;padding:18px}#topics label{display:block}.hint{color:#555}nav{position:sticky;top:0;background:white;padding:8px}a{color:#1461c4}</style><h1>AI4S 分类人工确认</h1><p>该文件仅含公开资料。每条需要阅读材料后确认；现有自动标签不会直接成为金标准。评审者可看留出材料，分类规则作者冻结配置前应只看开发集。先选证据支持的最具体主题；只能支持父类时选 broad_only 并取消 fine_applicable。完整可接受替代集合可在高级字段中编辑。</p><nav><input id="reviewer" placeholder="评审者名称"><select id="split"><option value="all">全部</option><option value="dev">开发集</option><option value="holdout">留出集（仅评审者）</option></select><button id="prev">上一条</button><button id="next">下一条</button><button id="save">确认并保存此条</button><button id="export">导出确认文件</button><input id="import" type="file" accept="application/json"><span id="progress"></span></nav><article id="article"></article><fieldset><legend>独立内容属性</legend><label>scope <select id="scope"><option>research</option><option>non_research</option><option>unknown</option></select></label><label>content_kind <select id="kind"><option>paper</option><option>technicalreport</option><option>modelrelease</option><option>engineeringupdate</option><option>organizationpolicy</option></select></label><label>status <select id="status"><option>classified</option><option>broad_only</option><option>low_confidence</option><option>insufficient_evidence</option><option>taxonomy_gap</option></select></label><label><input id="fine" type="checkbox" checked>fine_applicable</label><p>领域（逗号分隔）：<input id="domains" value="web:materials" size="60"></p></fieldset><fieldset><legend>研究主题</legend><div id="topics"></div><label>高级：完整替代集合 JSON（留空则使用勾选主题）<textarea id="alternatives" placeholder='[["zt-..."],["zt-..."]]'></textarea></label></fieldset><label>公开材料中的判断依据（必填）<textarea id="reason"></textarea></label><label><input id="confirmed" type="checkbox">我已阅读公开材料并确认本条标签</label><p id="message" role="status"></p><script>const data='''+payload+''';let position=0;const store='ai4s-annotation-'+data.records.map(x=>x.id).sort().join(':');let labels=JSON.parse(localStorage.getItem(store)||'{}');const $=x=>document.getElementById(x);const text=(el,value)=>{el.textContent=value||''};let filtered=()=>data.records.filter(r=>$('split').value==='all'||r.split===$('split').value);function render(){const rows=filtered();position=Math.max(0,Math.min(position,rows.length-1));const r=rows[position];if(!r)return;const g=labels[r.id];$('article').replaceChildren();const h=document.createElement('h2');text(h,r.item.title);const a=document.createElement('a');a.href=r.item.url;a.target='_blank';a.rel='noopener';text(a,'打开公开原文');const p=document.createElement('p');text(p,r.item.excerpt||'公开摘要缺失，请阅读原文；无法判断时标证据不足。');$('article').append(h,a,p);text($('progress'),`${position+1}/${rows.length} · ${r.split} · 已确认 ${Object.keys(labels).length}/${data.records.length}`);$('scope').value=g?.scope||'unknown';$('kind').value=g?.content_kind||(r.item.type==='paper'?'paper':'technicalreport');$('status').value=g?.status||'insufficient_evidence';$('fine').checked=g?.fine_applicable??true;$('domains').value=(g?.domain_facets||[]).join(',');$('reason').value=g?.public_reason||'';$('alternatives').value=g?JSON.stringify(g.acceptable_topic_sets):'';$('confirmed').checked=!!g;$('topics').replaceChildren();for(const t of data.taxonomy.topics){const label=document.createElement('label');const check=document.createElement('input');check.type='checkbox';check.value=t.id;check.checked=!!g?.acceptable_topic_sets?.[0]?.includes(t.id);label.append(check,document.createTextNode(t.path));$('topics').append(label)}text($('message'),'')};function save(){try{if(!$('confirmed').checked||!$('reason').value.trim()||!$('reviewer').value.trim())throw Error('请填写评审者和公开依据，并勾选人工确认。');const selected=[...$('topics').querySelectorAll('input:checked')].map(x=>x.value);const alternatives=$('alternatives').value.trim()?JSON.parse($('alternatives').value):[selected];const g={human_confirmed:true,reviewer:$('reviewer').value.trim(),reviewed_at:new Date().toISOString(),scope:$('scope').value,content_kind:$('kind').value,domain_facets:$('domains').value.split(',').map(x=>x.trim()).filter(Boolean),acceptable_topic_sets:alternatives,fine_applicable:$('fine').checked,status:$('status').value,public_reason:$('reason').value.trim()};labels[filtered()[position].id]=g;localStorage.setItem(store,JSON.stringify(labels));text($('message'),'已保存到本机。最终仍须通过 CLI 校验与独立复核。')}catch(e){text($('message'),e.message)}}$('save').onclick=save;$('next').onclick=()=>{position++;render()};$('prev').onclick=()=>{position--;render()};$('split').onchange=()=>{position=0;render()};$('export').onclick=()=>{const blob=new Blob([JSON.stringify({schema_version:1,labels},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ai4s-human-labels.json';a.click();URL.revokeObjectURL(a.href)};$('import').onchange=async e=>{try{const v=JSON.parse(await e.target.files[0].text());if(v.schema_version!==1||!v.labels)throw Error('不支持的导入格式');const ids=new Set(data.records.map(r=>r.id));for(const id of Object.keys(v.labels))if(!ids.has(id))throw Error('未知条目 ID');labels={...labels,...v.labels};localStorage.setItem(store,JSON.stringify(labels));render()}catch(e){text($('message'),e.message)}};render();</script></html>'''

def main():
    p=argparse.ArgumentParser();p.add_argument('--dataset',type=pathlib.Path,default=ROOT/'site/topics/evaluation/annotation-dataset.json');p.add_argument('--html',type=pathlib.Path);p.add_argument('--import-labels',type=pathlib.Path);p.add_argument('--output',type=pathlib.Path);a=p.parse_args();data=json.loads(a.dataset.read_text())
    if a.html:a.html.parent.mkdir(parents=True,exist_ok=True);a.html.write_text(review_html(data));print('Review HTML written')
    if a.import_labels:
        imported=json.loads(a.import_labels.read_text());known={r['id'] for r in data['records']}
        if set(imported)!={'schema_version','labels'} or imported['schema_version']!=1 or not set(imported['labels'])<=known:raise ValueError('Unknown import fields or IDs')
        for row in data['records']:
            if row['id'] in imported['labels']:row['gold']=validate_gold(imported['labels'][row['id']],data['taxonomy'])
        if not a.output:raise ValueError('--output required; frozen source is preserved')
        a.output.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'confirmed_n':sum(r['gold'] is not None for r in data['records']),'dataset_sha256':digest(data)}))
if __name__=='__main__':main()
